// A single row of a query result.
//
// Values are positional: the value at index `i` corresponds to the column
// name at index `i` of the accompanying `list<column-name>` header returned
// by `query`. Carrying the column names once alongside the row stream (rather
// than repeating a name with every value) keeps large result sets compact.
type Row = []PgValue
